#!/bin/bash
# Rebuilds statistics.html from the generated partials.
#
# The body is generated by the module generator from the twenty-section
# specification, so every numbered sub-item is present by construction and
# the figures stay consistent across sections.
set -e
cd "$(dirname "$0")"

python3 _gen_statistics.py
cat _statistics.css _statistics2.css > _statistics-build.css
python3 _compose.py _sbhead.html statistics _statistics-build.css

{
  cat _sbhead.html
  cat _sb2body.html
  cat _sb2js.js
  printf '</body>\n</html>\n'
} > statistics.html

python3 - <<'PYEOF'
import pathlib
p = pathlib.Path('statistics.html')
s = p.read_text()
s = s.replace('<title>Module — GOLDEN FINANCIAL SERVICES</title>',
              '<title>Statistics — GOLDEN FINANCIAL SERVICES</title>')
p.write_text(s)
print('built statistics.html', len(s), 'bytes')
PYEOF

python3 inject_backnav.py statistics.html
